CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS campaigns (id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memberships (campaign_id TEXT NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('master','editor','viewer')),PRIMARY KEY(campaign_id,user_id),FOREIGN KEY(campaign_id) REFERENCES campaigns(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL,email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('master','editor','viewer')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(campaign_id,email));
CREATE TABLE IF NOT EXISTS entries (id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL,parent_id TEXT,kind TEXT NOT NULL CHECK(kind IN ('folder','person','location','item','faction','event','article')),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',body TEXT NOT NULL DEFAULT '',secret_body TEXT NOT NULL DEFAULT '',visibility TEXT NOT NULL DEFAULT 'published' CHECK(visibility IN ('published','master')),image_key TEXT,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(campaign_id) REFERENCES campaigns(id));
CREATE TABLE IF NOT EXISTS revisions(id TEXT PRIMARY KEY,entry_id TEXT NOT NULL,snapshot TEXT NOT NULL,edited_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_entries_campaign ON entries(campaign_id,parent_id);
CREATE INDEX IF NOT EXISTS idx_revisions_entry ON revisions(entry_id,created_at);
